<?php
require_once "../config/database.php"; require_once "../includes/auth.php"; require_role("teacher"); $page_title="Посещаемость";
$q=$pdo->prepare("SELECT id FROM teachers WHERE user_id=?");$q->execute([$_SESSION['user']['id']]);$tid=$q->fetchColumn();
$st=$pdo->prepare("SELECT l.id,l.lesson_date,s.name subject_name,g.name group_name FROM lessons l JOIN subjects s ON s.id=l.subject_id JOIN groups g ON g.id=l.group_id WHERE l.teacher_id=? ORDER BY l.lesson_date DESC,l.start_time DESC");$st->execute([$tid]);$lessons=$st->fetchAll();
$lesson_id=(int)($_GET['lesson']??($lessons[0]['id']??0));$lesson=null;$students=[];
if($lesson_id){$q=$pdo->prepare("SELECT l.*,s.name subject_name,g.name group_name FROM lessons l JOIN subjects s ON s.id=l.subject_id JOIN groups g ON g.id=l.group_id WHERE l.id=? AND l.teacher_id=?");$q->execute([$lesson_id,$tid]);$lesson=$q->fetch();if($lesson){$q=$pdo->prepare("SELECT st.*,a.status attendance_status,a.comment attendance_comment FROM students st LEFT JOIN attendance a ON a.student_id=st.id AND a.lesson_id=? WHERE st.group_id=? ORDER BY st.surname,st.name");$q->execute([$lesson_id,$lesson['group_id']]);$students=$q->fetchAll();}}
include "../includes/header.php"; ?>
<div class="panel"><div class="toolbar"><form><select name="lesson" onchange="this.form.submit()" class="search"><?php foreach($lessons as $l): ?><option value="<?=$l['id']?>" <?=$l['id']==$lesson_id?'selected':''?>><?=date('d.m.Y',strtotime($l['lesson_date']))?> — <?=htmlspecialchars($l['subject_name'])?> — <?=htmlspecialchars($l['group_name'])?></option><?php endforeach;?></select></form><?php if($lesson): ?><span class="badge present"><?=htmlspecialchars($lesson['group_name'])?></span><?php endif;?></div>
<?php if($lesson): ?><form onsubmit="return saveAttendance(this)"><input type="hidden" name="lesson_id" value="<?=$lesson_id?>"><div class="actions" style="margin-bottom:15px"><button type="button" class="btn secondary" onclick="document.querySelectorAll('.attendance-select').forEach(x=>x.value='PRESENT')">Все присутствуют</button><button type="button" class="btn secondary" onclick="document.querySelectorAll('.attendance-select').forEach(x=>x.value='ABSENT')">Все отсутствуют</button><button class="btn success">Сохранить посещаемость</button></div>
<div class="table-wrap"><table><tr><th>№</th><th>Студент</th><th>Статус</th><th>Комментарий</th></tr>
<?php foreach($students as $i=>$st): ?><tr><td><?=$i+1?></td><td><b><?=htmlspecialchars("$st[surname] $st[name] $st[patronymic]")?></b></td><td><select class="attendance-select" name="status[<?=$st['id']?>]"><?php foreach(['PRESENT'=>'Присутствует','ABSENT'=>'Отсутствует','LATE'=>'Опоздал','EXCUSED'=>'Уважительная причина'] as $v=>$label): ?><option value="<?=$v?>" <?=($st['attendance_status']??'PRESENT')===$v?'selected':''?>><?=$label?></option><?php endforeach;?></select></td><td><input name="comment[<?=$st['id']?>]" value="<?=htmlspecialchars($st['attendance_comment']??'')?>" placeholder="необязательно"></td></tr><?php endforeach;?>
</table></div></form><?php else: ?><div class="empty">Создайте занятие, чтобы отметить посещаемость.</div><?php endif;?></div><div id="toast" class="toast"></div><?php include "../includes/footer.php"; ?>